// ## src/utils/AppError.js
export class AppError extends Error {
  constructor(message, statusCode = 500, details) {
    super(message)
    this.name = this.constructor.name
    this.statusCode = statusCode
    this.isOperational = true
    this.details = details
    Error.captureStackTrace(this, this.constructor)
  }
}
export class NotFoundError extends AppError {
  constructor(what = 'Resource') { super(`${what} not found`, 404) }
}
export class BadRequestError extends AppError {
  constructor(message = 'Bad request', details) { super(message, 400, details) }
}
export class UnauthorizedError extends AppError {
  constructor(message = 'Not authenticated') { super(message, 401) }
}

// ## src/middleware/errorHandler.js
import { AppError } from '../utils/AppError.js'

function normalize(err) {
  if (err instanceof AppError) return err
  if (err.name === 'CastError') return new AppError(`Invalid ${err.path}: ${err.value}`, 400)
  if (err.code === 11000) {
    const field = Object.keys(err.keyValue ?? {})[0]
    return new AppError(`Duplicate value for ${field}`, 409)
  }
  if (err.name === 'ValidationError') {
    const details = Object.values(err.errors).map((e) => e.message)
    return new AppError('Validation failed', 400, details)
  }
  if (err.name === 'JsonWebTokenError') return new AppError('Invalid token', 401)
  if (err.name === 'TokenExpiredError') return new AppError('Token expired', 401)
  if (err.type === 'entity.parse.failed') return new AppError('Malformed JSON body', 400)
  return err
}

export function errorHandler(err, req, res, next) {
  if (res.headersSent) return next(err)
  const e = normalize(err)
  const known = e instanceof AppError
  if (!known) console.error('UNEXPECTED ERROR', err)

  res.status(known ? e.statusCode : 500).json({
    status: 'error',
    message: known ? e.message : 'Internal Server Error',
    ...(e.details && { details: e.details }),
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
  })
}

