// ## src/controllers/productController.js
import mongoose from 'mongoose'
import Product from '../models/Product.js'

const pick = (obj, keys) => Object.fromEntries(keys.filter((k) => k in obj).map((k) => [k, obj[k]]))
const FIELDS = ['name', 'price', 'category', 'stock']

function checkId(id) {
  if (!mongoose.isValidObjectId(id)) {
    throw Object.assign(new Error('Invalid id'), { status: 400 })
  }
}
const notFound = () => Object.assign(new Error('Product not found'), { status: 404 })

export const listProducts = async (req, res) => {
  res.json(await Product.find().lean())
}

export const getProduct = async (req, res) => {
  checkId(req.params.id)
  const product = await Product.findById(req.params.id)
  if (!product) throw notFound()
  res.json(product)
}

export const createProduct = async (req, res) => {
  const product = await Product.create(pick(req.body ?? {}, FIELDS))
  res.status(201).json(product)
}

export const updateProduct = async (req, res) => {
  checkId(req.params.id)
  const product = await Product.findByIdAndUpdate(
    req.params.id, pick(req.body ?? {}, FIELDS), { returnDocument: 'after', runValidators: true }
  )
  if (!product) throw notFound()
  res.json(product)
}

export const deleteProduct = async (req, res) => {
  checkId(req.params.id)
  const product = await Product.findByIdAndDelete(req.params.id)
  if (!product) throw notFound()
  res.status(204).end()
}

