import mongoose from 'mongoose'
import Order from '../models/Order.js'   // model from the aggregation topic
import Product from '../models/Product.js'

export async function placeOrder(userId, lines) {
  const session = await mongoose.startSession()
  try {
    let order
    await session.withTransaction(async () => {
      const items = []
      for (const { productId, qty } of lines) {
        const product = await Product.findOneAndUpdate(
          { _id: productId, stock: { $gte: qty } },          // atomic stock check
          { $inc: { stock: -qty } },
          { returnDocument: 'after', session }
        )
        if (!product) throw Object.assign(new Error('Out of stock'), { status: 409 })
        items.push({ name: product.name, price: product.price, qty })
      }
      ;[order] = await Order.create([{ user: userId, items }], { session })
    })
    return order
  } finally {
    await session.endSession()
  }
}

