import { Router } from 'express'
import { generateSecret, generateURI, verify } from 'otplib'   // otplib v13 API
import QRCode from 'qrcode'
import User from '../models/User.js'
import { protect } from '../middleware/protect.js'

const router = Router()

// step 1: user enables 2FA
router.post('/2fa/setup', protect, async (req, res) => {
  const secret = generateSecret()
  await User.findByIdAndUpdate(req.user.id, { twoFactorTempSecret: secret })
  const otpauth = generateURI({ issuer: 'MyApp', label: req.user.email, secret })
  res.json({ qr: await QRCode.toDataURL(otpauth) })     // show as <img src=...>
})

// step 2: user confirms with the first code from the authenticator app
router.post('/2fa/enable', protect, async (req, res) => {
  const user = await User.findById(req.user.id).select('+twoFactorTempSecret')
  const result = await verify({ token: req.body.code, secret: user.twoFactorTempSecret })
  if (!result.valid) return res.status(400).json({ error: 'Invalid code' })
  user.twoFactorSecret = user.twoFactorTempSecret
  user.twoFactorEnabled = true
  await user.save()
  res.json({ message: '2FA enabled' })
})

import crypto from 'node:crypto'
import { Router } from 'express'
import User from '../models/User.js'
import { sendEmail } from '../utils/email.js'

const router = Router()
const sha256 = (s) => crypto.createHash('sha256').update(s).digest('hex')

router.post('/forgot-password', async (req, res) => {
  const user = await User.findOne({ email: req.body.email })
  if (user) {
    const token = crypto.randomBytes(32).toString('hex')
    user.resetTokenHash = sha256(token)
    user.resetTokenExpires = Date.now() + 15 * 60 * 1000
    await user.save({ validateBeforeSave: false })

    const link = `${process.env.CLIENT_URL}/reset-password?token=${token}`
    await sendEmail(user.email, 'Reset your password', `Click to reset (valid 15 min): ${link}`)
  }
  // same answer either way
  res.json({ message: 'If that email exists, a reset link has been sent' })
})

router.post('/reset-password', async (req, res) => {
  const { token, password } = req.body
  const user = await User.findOne({
    resetTokenHash: sha256(token ?? ''),
    resetTokenExpires: { $gt: Date.now() },
  })
  if (!user) return res.status(400).json({ error: 'Token is invalid or expired' })

  user.password = password                 // pre-save hook hashes it
  user.resetTokenHash = undefined
  user.resetTokenExpires = undefined
  user.tokenVersion = (user.tokenVersion ?? 0) + 1      // invalidates old refresh tokens
  await user.save()
  res.json({ message: 'Password updated. Please log in.' })
})

export default router

// ## src/middleware/validate.js
export const validate = (schemas) => (req, res, next) => {
  const errors = []
  req.validated = {}
  for (const part of ['params', 'query', 'body']) {
    if (!schemas[part]) continue
    const result = schemas[part].safeParse(req[part] ?? {})
    if (!result.success) {
      for (const issue of result.error.issues) {
        errors.push({ in: part, field: issue.path.join('.'), message: issue.message })
      }
    } else {
      req.validated[part] = result.data
    }
  }
  if (errors.length) return res.status(400).json({ status: 'fail', errors })
  next()
}

