const httpServer = http.createServer(app)
const io = new Server(httpServer, {
  cors: { origin: process.env.CLIENT_URL ?? 'http://localhost:5173' },
})

// simple auth
io.use((socket, next) => {
  const { username } = socket.handshake.auth
  if (!username) return next(new Error('username required'))
  socket.data.username = username
  next()
})

io.on('connection', (socket) => {
  console.log(`${socket.data.username} connected`)

  socket.on('join', (room) => {
    socket.join(room)
    io.to(room).emit('system', `${socket.data.username} joined ${room}`)
  })

  socket.on('message', ({ room, text }, ack) => {
    io.to(room).emit('message', { user: socket.data.username, text, at: Date.now() })
    ack?.({ ok: true })
  })

  socket.on('disconnect', () => console.log(`${socket.data.username} left`))
})

