// ## src/middleware/validate.js
export const validate = (schemas) => (req, res, next) => {
  const errors = []
  req.validated = {}
  for (const part of ['params', 'query', 'body']) {
    if (!schemas[part]) continue
    const result = schemas[part].safeParse(req[part] ?? {})
    if (result.success) req.validated[part] = result.data
    else for (const i of result.error.issues) errors.push({ in: part, field: i.path.join('.'), message: i.message })
  }
  if (errors.length) return res.status(400).json({ message: 'Validation failed', errors })
  next()
}

// ## src/middleware/auth.js
import jwt from 'jsonwebtoken'
import User from '../models/User.js'

export async function protect(req, res, next) {
  const [scheme, token] = (req.get('authorization') ?? '').split(' ')
  if (scheme !== 'Bearer' || !token) return res.status(401).json({ message: 'Please log in' })
  try {
    const { sub } = jwt.verify(token, process.env.JWT_SECRET, { algorithms: ['HS256'] })
    const user = await User.findById(sub)
    if (!user) return res.status(401).json({ message: 'User no longer exists' })
    req.user = user
    next()
  } catch {
    res.status(401).json({ message: 'Invalid or expired token' })
  }
}

// ## src/middleware/errorHandler.js
export function errorHandler(err, req, res, next) {
  if (res.headersSent) return next(err)
  let status = err.status ?? 500
  let message = err.message
  if (err.code === 11000) { status = 409; message = 'Email already registered' }
  else if (err.name === 'CastError') { status = 400; message = 'Invalid id' }
  else if (err.type === 'entity.parse.failed') { status = 400; message = 'Malformed JSON body' }
  if (status >= 500) { console.error(err); message = 'Internal Server Error' }
  res.status(status).json({ message })
}

