import mongoose from 'mongoose'
import Note from '../models/Note.js'

const escapeRegex = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

// every lookup includes the owner: someone else's note looks exactly like a missing one
async function findMine(req) {
  const { id } = req.params
  const note = mongoose.isValidObjectId(id) ? await Note.findOne({ _id: id, owner: req.user._id }) : null
  if (!note) throw Object.assign(new Error('Note not found'), { status: 404 })
  return note
}

export const listNotes = async (req, res) => {
  const { q, tag, pinned, archived, page, limit } = req.validated.query
  const filter = { owner: req.user._id, archived }
  if (pinned !== undefined) filter.pinned = pinned
  if (tag) filter.tags = tag
  if (q) {
    const rx = { $regex: escapeRegex(q), $options: 'i' }
    filter.$or = [{ title: rx }, { content: rx }]
  }
  const [data, total] = await Promise.all([
    Note.find(filter).sort({ pinned: -1, updatedAt: -1 }).skip((page - 1) * limit).limit(limit),
    Note.countDocuments(filter),
  ])
  res.json({ data, meta: { page, limit, total, totalPages: Math.ceil(total / limit) } })
}

export const getNote = async (req, res) => res.json(await findMine(req))

export const createNote = async (req, res) => {
  const note = await Note.create({ ...req.validated.body, owner: req.user._id })
  res.status(201).json(note)
}

export const updateNote = async (req, res) => {
  const note = await findMine(req)
  Object.assign(note, req.validated.body)
  await note.save()
  res.json(note)
}

export const deleteNote = async (req, res) => {
  const note = await findMine(req)
  await note.deleteOne()
  res.status(204).end()
}

