// ## src/controllers/authController.js
import jwt from 'jsonwebtoken'
import User from '../models/User.js'

const sign = (u) => jwt.sign({ sub: u.id }, process.env.JWT_SECRET, { expiresIn: '1d' })

export const register = async (req, res) => {
  const { name, password } = req.body ?? {}
  const user = await User.create({ name, password })
  res.status(201).json({ token: sign(user), user: { id: user.id, name: user.name } })
}

export const login = async (req, res) => {
  const { name, password } = req.body ?? {}
  const user = typeof name === 'string' && typeof password === 'string'
    ? await User.findOne({ name }).select('+password')
    : null
  if (!user || !(await user.matchPassword(password))) {
    return res.status(401).json({ message: 'Invalid name or password' })
  }
  res.json({ token: sign(user), user: { id: user.id, name: user.name } })
}

// ## src/controllers/messageController.js
import mongoose from 'mongoose'
import Message from '../models/Message.js'

export const ROOM_PATTERN = /^[a-z0-9-]{1,30}$/

export const history = async (req, res) => {
  const { room } = req.params
  if (!ROOM_PATTERN.test(room)) return res.status(400).json({ message: 'Invalid room name' })

  const limit = Math.min(Math.max(parseInt(req.query.limit) || 30, 1), 100)
  const filter = { room }
  if (typeof req.query.before === 'string' && mongoose.isValidObjectId(req.query.before)) {
    filter._id = { $lt: req.query.before }                          // cursor pagination
  }

  const items = await Message.find(filter).sort({ _id: -1 }).limit(limit + 1).populate('user', 'name')
  const hasMore = items.length > limit
  const page = hasMore ? items.slice(0, limit) : items
  res.json({ data: page.reverse(), nextCursor: hasMore ? page[0]._id : null })
}

