// ## src/api/client.js
import axios from 'axios'

export const api = axios.create({ baseURL: import.meta.env.VITE_API_URL ?? '/api', withCredentials: true })

let accessToken = null
let refreshing = null
export const setAccessToken = (token) => { accessToken = token }

api.interceptors.request.use((config) => {
  if (accessToken) config.headers.Authorization = `Bearer ${accessToken}`
  return config
})

api.interceptors.response.use(
  (response) => response,
  async (error) => {
    const original = error.config
    const isAuthRoute = original?.url?.startsWith('/auth/')
    if (error.response?.status !== 401 || original._retried || isAuthRoute) return Promise.reject(error)

    original._retried = true
    try {
      refreshing ??= api.post('/auth/refresh').finally(() => { refreshing = null })   // one refresh for many requests
      const { data } = await refreshing
      setAccessToken(data.accessToken)
      original.headers.Authorization = `Bearer ${data.accessToken}`
      return api(original)
    } catch (refreshError) {
      setAccessToken(null)
      window.dispatchEvent(new Event('auth:expired'))
      return Promise.reject(refreshError)
    }
  }
)

// ## src/context/AuthContext.jsx
import { createContext, useContext, useEffect, useState, useCallback } from 'react'
import { api, setAccessToken } from '../api/client.js'

const AuthContext = createContext(null)
export const useAuth = () => useContext(AuthContext)

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null)
  const [loading, setLoading] = useState(true)

  const applySession = useCallback(({ accessToken, user }) => {
    setAccessToken(accessToken)
    setUser(user)
  }, [])

  // on page load: try to restore the session with the refresh cookie
  useEffect(() => {
    api.post('/auth/refresh')
      .then(({ data }) => applySession(data))
      .catch(() => setUser(null))
      .finally(() => setLoading(false))

    const onExpired = () => setUser(null)
    window.addEventListener('auth:expired', onExpired)
    return () => window.removeEventListener('auth:expired', onExpired)
  }, [applySession])

  const login = async (email, password) => {
    const { data } = await api.post('/auth/login', { email, password })
    applySession(data)
  }

  const logout = async () => {
    await api.post('/auth/logout').catch(() => {})
    setAccessToken(null)
    setUser(null)
  }

  return <AuthContext.Provider value={{ user, loading, login, logout, setUser }}>{children}</AuthContext.Provider>
}

